<?php
/** Bounded read-only automation health monitoring. @package AIContentStudio */
if(!defined('ABSPATH')){exit;}
final class AICS_Automation_Health_Monitor{
	public const HOOK='aics_automation_health_check',OPTION='aics_automation_health_snapshot',LOCK='aics_automation_health_scan_lock';private const LIMIT=100,STORED_FINDINGS=50,SCHEMA=1;
	private AICS_Automation_Run_Repository $runs;private AICS_Automation_Profile_Repository $profiles;private AICS_Article_Repository $articles;private AICS_Automation_Stale_Run_Detector $detector;
	public function __construct(){ $this->runs=new AICS_Automation_Run_Repository();$this->profiles=new AICS_Automation_Profile_Repository();$this->articles=new AICS_Article_Repository();$this->detector=new AICS_Automation_Stale_Run_Detector();}
	public static function register():void{add_action(self::HOOK,array(self::class,'run_scheduled'));}
	public static function run_scheduled():void{(new self())->scan();}
	public function get_snapshot(bool $refresh_if_stale=false):array{$snapshot=get_option(self::OPTION,array());if(!$this->valid($snapshot)||($refresh_if_stale&&$this->is_stale($snapshot))){return $this->scan();}return $snapshot;}
	public function findings_for_run($run_id):array{$id=absint($run_id);$snapshot=$this->get_snapshot(false);return array_values(array_filter($snapshot['findings']??array(),static fn($f)=>$id>0&&absint($f['run_id']??0)===$id));}
	public function scan():array{$previous=get_option(self::OPTION,array());$stamp=time();$lock=(int)get_option(self::LOCK,0);if($lock&&$lock>$stamp-300){return $this->valid($previous)?$previous:$this->unknown();}if($lock){delete_option(self::LOCK);}if(!add_option(self::LOCK,$stamp,'','no')){return $this->valid($previous)?$previous:$this->unknown();}try{if(!$this->runs->table_exists()||!$this->profiles->table_exists()){return $this->store($this->unknown());}$now=current_time('mysql',true);$thresholds=$this->detector->thresholds();$cutoffs=array('running'=>gmdate('Y-m-d H:i:s',time()-$thresholds['running']),'queued'=>gmdate('Y-m-d H:i:s',time()-$thresholds['queued']),'retry'=>gmdate('Y-m-d H:i:s',time()-$thresholds['retry']));$candidates=$this->runs->get_health_candidate_runs($now,$cutoffs,self::LIMIT);$post_runs=$this->runs->get_active_runs_with_posts_for_health(self::LIMIT);$truncated=count($candidates)>self::LIMIT||count($post_runs)>self::LIMIT;$runs=array();foreach(array_merge(array_slice($candidates,0,self::LIMIT),array_slice($post_runs,0,self::LIMIT)) as $run){$runs[absint($run['id'])]=$run;}$overdue=$this->profiles->get_overdue_profiles_for_health_check(gmdate('Y-m-d H:i:s',time()-$thresholds['profile']),self::LIMIT);$truncated=$truncated||count($overdue)>self::LIMIT;$overdue=array_slice($overdue,0,self::LIMIT);$active_profile_ids=$this->runs->get_nonterminal_profile_ids(array_column($overdue,'id'));$overdue=array_values(array_filter($overdue,static fn($p)=>!in_array(absint($p['id']),$active_profile_ids,true)));$multiple=$this->runs->get_active_run_counts_by_profile(self::LIMIT);$associations=$this->articles->get_post_associations_for_health(array_keys($runs),self::LIMIT);$truncated=$truncated||count($associations)>self::LIMIT;$findings=$this->detector->detect(array_values($runs),$overdue,$multiple,array_slice($associations,0,self::LIMIT),$now);$active_profiles=$this->profiles->count_active_profiles();$cron=$this->cron_findings($active_profiles,$now);$findings=array_merge($findings,$cron);$critical=count(array_filter($findings,static fn($f)=>'critical'===$f['severity']));$warnings=count(array_filter($findings,static fn($f)=>'warning'===$f['severity']));$status=$critical?'critical':($warnings?'warning':'healthy');$run_ids=array_values(array_unique(array_filter(array_map('absint',array_column($findings,'run_id')))));$profile_ids=array_values(array_unique(array_filter(array_map('absint',array_column($findings,'profile_id')))));$snapshot=array('schema_version'=>self::SCHEMA,'overall_status'=>$status,'checked_at'=>$now,'active_run_count'=>$this->runs->get_operational_counts()['active'],'active_profile_count'=>$active_profiles,'stale_run_count'=>count(array_filter($findings,static fn($f)=>in_array($f['code'],array('stale_running_expired_lock','running_without_lock','queued_not_advancing'),true))),'overdue_retry_count'=>count(array_filter($findings,static fn($f)=>'retry_overdue'===$f['code'])),'blocked_profile_count'=>count(array_unique(array_filter(array_column(array_filter($findings,static fn($f)=>in_array($f['code'],array('terminal_run_holds_profile_reservation','failed_run_holds_profile_reservation','multiple_active_runs_for_profile','reservation_profile_mismatch'),true)),'profile_id')))),'cron_issue_count'=>count($cron),'critical_issue_count'=>$critical,'warning_issue_count'=>$warnings,'truncated'=>$truncated,'affected_run_ids'=>array_slice($run_ids,0,20),'affected_profile_ids'=>array_slice($profile_ids,0,20),'findings'=>array_slice($findings,0,self::STORED_FINDINGS),'cron'=>array('dispatcher'=>false!==wp_next_scheduled(AICS_Automation_Scheduler::HOOK),'worker'=>false!==wp_next_scheduled(AICS_Automation_Scheduler::WORKER_HOOK),'health_check'=>false!==wp_next_scheduled(self::HOOK)));return $this->store($snapshot);}finally{delete_option(self::LOCK);}}
	private function cron_findings(int $active,string $now):array{$d=false!==wp_next_scheduled(AICS_Automation_Scheduler::HOOK);$w=false!==wp_next_scheduled(AICS_Automation_Scheduler::WORKER_HOOK);$h=false!==wp_next_scheduled(self::HOOK);$out=array();if(!$d&&!$w&&$active){$out[]=$this->cron('dispatcher_and_worker_missing','critical',$now);}else{if(!$d&&$active){$out[]=$this->cron('dispatcher_missing','warning',$now);}if(!$w&&$active){$out[]=$this->cron('worker_missing','warning',$now);}}if(!$h){$out[]=$this->cron('health_check_missing','warning',$now);}return $out;}
	private function cron(string $code,string $severity,string $now):array{return array('code'=>$code,'severity'=>$severity,'entity_type'=>'cron','entity_id'=>0,'run_id'=>0,'profile_id'=>0,'recommended_action'=>'review_cron','detected_at'=>$now);}
	public function is_stale(array $snapshot):bool{$checked=strtotime((string)($snapshot['checked_at']??'').' UTC');return !$checked||$checked<time()-$this->detector->thresholds()['snapshot'];}
	private function valid($s):bool{return is_array($s)&&self::SCHEMA===($s['schema_version']??null)&&in_array($s['overall_status']??'',array('healthy','warning','critical','unknown'),true)&&is_array($s['findings']??null);}
	private function store(array $snapshot):array{if(false===get_option(self::OPTION,false)){add_option(self::OPTION,$snapshot,'','no');}else{update_option(self::OPTION,$snapshot,false);}return $snapshot;}
	private function unknown():array{return array('schema_version'=>self::SCHEMA,'overall_status'=>'unknown','checked_at'=>'','active_run_count'=>0,'active_profile_count'=>0,'stale_run_count'=>0,'overdue_retry_count'=>0,'blocked_profile_count'=>0,'cron_issue_count'=>0,'critical_issue_count'=>0,'warning_issue_count'=>0,'truncated'=>false,'affected_run_ids'=>array(),'affected_profile_ids'=>array(),'findings'=>array(),'cron'=>array('dispatcher'=>false,'worker'=>false,'health_check'=>false));}
	public static function labels():array{return array('stale_running_expired_lock'=>'Run appears interrupted','running_without_lock'=>'Running run has no active worker lock','queued_not_advancing'=>'Queued run has not advanced','retry_overdue'=>'Scheduled retry is overdue','terminal_run_holds_profile_reservation'=>'Completed or cancelled run still blocks its automation profile','failed_run_holds_profile_reservation'=>'Failed run still blocks its automation profile','multiple_active_runs_for_profile'=>'Multiple active runs are using the same automation profile','reservation_profile_mismatch'=>'Run profile reservation does not match its automation profile','overdue_profile_without_run'=>'Automation profile is overdue but no run was created','missing_expected_post'=>'Associated WordPress post is missing','ownership_conflict'=>'WordPress post ownership could not be verified','active_run_unknown_step'=>'Run is using an unsupported workflow step','retry_without_retry_time'=>'Retrying run has no retry time','completed_run_not_finalized'=>'Completed run has incomplete finalization data','dispatcher_missing'=>'Automation dispatcher cron event is missing','worker_missing'=>'Automation worker cron event is missing','health_check_missing'=>'Automation health-check cron event is missing','dispatcher_and_worker_missing'=>'Automation dispatcher and worker cron events are missing','health_snapshot_stale'=>'Automation health information is outdated');}
}
